MidisInstance::IPCStableHashFunction MidisInstance::MessageToMethodInfo_(mojo::Message& message) {
#if !BUILDFLAG(IS_FUCHSIA)
  switch (message.name()) {
    case internal::kMidisInstance_Init_Name: {
      return &MidisInstance::Init_Sym::IPCStableHash;
    }
  }
#endif  // !BUILDFLAG(IS_FUCHSIA)
  return nullptr;
}


const char* MidisInstance::MessageToMethodName_(mojo::Message& message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (!is_response) {
    switch (message.name()) {
      case internal::kMidisInstance_Init_Name:
            return "Receive arc::mojom::MidisInstance::Init";
    }
  } else {
    switch (message.name()) {
      case internal::kMidisInstance_Init_Name:
            return "Receive reply arc::mojom::MidisInstance::Init";
    }
  }
  return "Receive unknown mojo message";
#else
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (is_response) {
    return "Receive mojo reply";
  } else {
    return "Receive mojo message";
  }
#endif // BUILDFLAG(MOJO_TRACE_ENABLED)
}

#if !BUILDFLAG(IS_FUCHSIA)
uint32_t MidisInstance::Init_Sym::IPCStableHash() {
  // This method's address is used for indetifiying the mojo method name after
  // symbolization. So each IPCStableHash should have a unique address.
  // We cannot use NO_CODE_FOLDING() here - it relies on the uniqueness of
  // __LINE__ value, which is not unique accross different mojo modules.
  // The code below is very similar to NO_CODE_FOLDING, but it uses a unique
  // hash instead of __LINE__.
  constexpr uint32_t kHash = base::MD5Hash32Constexpr(
          "(Impl)arc::mojom::MidisInstance::Init");
  const uint32_t hash = kHash;
  base::debug::Alias(&hash);
  return hash;
}
# endif // !BUILDFLAG(IS_FUCHSIA)

class MidisInstance_Init_ForwardToCallback
    : public mojo::MessageReceiver {
 public:
  MidisInstance_Init_ForwardToCallback(
      MidisInstance::InitCallback callback
      ) : callback_(std::move(callback)) {
  }

  MidisInstance_Init_ForwardToCallback(const MidisInstance_Init_ForwardToCallback&) = delete;
  MidisInstance_Init_ForwardToCallback& operator=(const MidisInstance_Init_ForwardToCallback&) = delete;

  bool Accept(mojo::Message* message) override;
 private:
  MidisInstance::InitCallback callback_;
};

MidisInstanceProxy::MidisInstanceProxy(mojo::MessageReceiverWithResponder* receiver)
    : receiver_(receiver) {
}

void MidisInstanceProxy::Init(
    ::mojo::PendingRemote<MidisHost> in_host_remote, InitCallback callback) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send arc::mojom::MidisInstance::Init", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("host_remote"), in_host_remote,
                        "<value of type ::mojo::PendingRemote<MidisHost>>");
   });
#endif

  const bool kExpectsResponse = true;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;
  
  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);
  
  mojo::Message message(
      internal::kMidisInstance_Init_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::arc::mojom::internal::MidisInstance_Init_Params_Data> params(
          message);
  params.Allocate();
  mojo::internal::Serialize<mojo::InterfacePtrDataView<::arc::mojom::MidisHostInterfaceBase>>(
      in_host_remote, &params->host_remote, &params.message());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      !mojo::internal::IsHandleOrInterfaceValid(params->host_remote),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_INVALID_HANDLE,
      "invalid host_remote in MidisInstance.Init request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(MidisInstance::Name_);
  message.set_method_name("Init");
#endif
  std::unique_ptr<mojo::MessageReceiver> responder(
      new MidisInstance_Init_ForwardToCallback(
          std::move(callback)));
  ::mojo::internal::SendMojoMessage(*receiver_, message, std::move(responder));
}
class MidisInstance_Init_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static MidisInstance::InitCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
    std::unique_ptr<MidisInstance_Init_ProxyToResponder> proxy(
        new MidisInstance_Init_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&MidisInstance_Init_ProxyToResponder::Run,
                          std::move(proxy));
  }

  ~MidisInstance_Init_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  MidisInstance_Init_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "MidisInstance::InitCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      );
};

bool MidisInstance_Init_ForwardToCallback::Accept(
    mojo::Message* message) {

  DCHECK(message->is_serialized());
  internal::MidisInstance_Init_ResponseParams_Data* params =
      reinterpret_cast<
          internal::MidisInstance_Init_ResponseParams_Data*>(
              message->mutable_payload());
  
  
  // Validation for MidisInstance.1
  bool success = true;
  MidisInstance_Init_ResponseParamsDataView input_data_view(params, message);
  
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        MidisInstance::Name_, 1, true);
    return false;
  }
  if (!callback_.is_null())
    std::move(callback_).Run();
  return true;
}

void MidisInstance_Init_ProxyToResponder::Run(
    ) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT0("mojom", "Send reply arc::mojom::MidisInstance::Init");
#endif
  
  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((false) ? mojo::Message::kFlagIsUrgent : 0);
  
  mojo::Message message(
      internal::kMidisInstance_Init_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::arc::mojom::internal::MidisInstance_Init_ResponseParams_Data> params(
          message);
  params.Allocate();

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(MidisInstance::Name_);
  message.set_method_name("Init");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

// static
bool MidisInstanceStubDispatch::Accept(
    MidisInstance* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kMidisInstance_Init_Name: {
      break;
    }
  }
  return false;
}

// static
bool MidisInstanceStubDispatch::AcceptWithResponder(
    MidisInstance* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kMidisInstance_Init_Name: {

      internal::MidisInstance_Init_Params_Data* params =
          reinterpret_cast<
              internal::MidisInstance_Init_Params_Data*>(
                  message->mutable_payload());
      
      
      // Validation for MidisInstance.1
      bool success = true;
      ::mojo::PendingRemote<MidisHost> p_host_remote{};
      MidisInstance_Init_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_host_remote =
            input_data_view.TakeHostRemote<decltype(p_host_remote)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            MidisInstance::Name_, 1, false);
        return false;
      }
      MidisInstance::InitCallback callback =
          MidisInstance_Init_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Init(        
        std::move(p_host_remote), std::move(callback));
      return true;
    }
  }
  return false;
}
