// static
bool StructTraits<::arc::mojom::MidisDeviceInfo::DataView, ::arc::mojom::MidisDeviceInfoPtr>::Read(
    ::arc::mojom::MidisDeviceInfo::DataView input,
    ::arc::mojom::MidisDeviceInfoPtr* output) {
  bool success = true;
  ::arc::mojom::MidisDeviceInfoPtr result(::arc::mojom::MidisDeviceInfo::New());
  
      if (success)
        result->card = input.card();
      if (success)
        result->device_num = input.device_num();
      if (success)
        result->num_subdevices = input.num_subdevices();
      if (success)
        result->flags = input.flags();
      if (success && !input.ReadName(&result->name))
        success = false;
      if (success && !input.ReadManufacturer(&result->manufacturer))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::arc::mojom::MidisRequest::DataView, ::arc::mojom::MidisRequestPtr>::Read(
    ::arc::mojom::MidisRequest::DataView input,
    ::arc::mojom::MidisRequestPtr* output) {
  bool success = true;
  ::arc::mojom::MidisRequestPtr result(::arc::mojom::MidisRequest::New());
  
      if (success)
        result->card = input.card();
      if (success)
        result->device_num = input.device_num();
      if (success)
        result->subdevice_num = input.subdevice_num();
  *output = std::move(result);
  return success;
}

